import * as THREE from './vendor/three.module.js';
export function assetURL(name){return globalThis.NYLON_ASSETS?.[name]||name}
export async function loadGeometry(name){const response=await fetch(assetURL('model/'+name+'.bin.gz'));if(!response.ok)throw Error('模型读取失败：'+response.status);if(!globalThis.DecompressionStream)throw Error('请使用新版 Chrome 或 Edge 打开');const stream=response.body.pipeThrough(new DecompressionStream('gzip')),buffer=await new Response(stream).arrayBuffer(),h=new DataView(buffer);if(h.getUint32(0,true)!==0x344c594e)throw Error('模型数据格式错误');const count=h.getUint32(4,true),ni=h.getUint32(8,true);if(buffer.byteLength!==16+count*20+ni*4)throw Error('模型数据不完整');const p=new Float32Array(buffer,16,count*3).slice();for(let i=0;i<p.length;i+=3){p[i]=(p[i]+.005175)*6.3;p[i+1]=(p[i+1]-1.073938/2)*6.3;p[i+2]*=6.3}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(p,3));g.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(buffer,16+count*12,count*2).slice(),2));g.setIndex(new THREE.BufferAttribute(new Uint32Array(buffer,16+count*20,ni).slice(),1));g.computeVertexNormals();g.computeBoundingSphere();return g}
export function loadTexture(name,color=false){return new Promise((resolve,reject)=>{new THREE.TextureLoader().load(assetURL('model/'+name),t=>{if(color)t.colorSpace=THREE.SRGBColorSpace;t.anisotropy=4;resolve(t)},undefined,()=>reject(Error('贴图加载失败：'+name)))})}
